SELECT  FROM task
WHERE status = 'RETRY_WAITING' AND next_retry_at <= #{now}
ORDER BY next_retry_at ASC LIMIT #{limit}

SELECT  FROM task
WHERE status = 'RUNNING' AND updated_at < #{threshold}
ORDER BY updated_at ASC LIMIT #{limit}

SELECT  FROM task
WHERE status = 'WAITING'
ORDER BY priority DESC, created_at ASC LIMIT #{limit}

