UPDATE task
SET status = 'WAITING', version = version + 1, updated_at = #{now}
WHERE id = #{taskId} AND version = #{expectedVer} AND status = 'RETRY_WAITING'

UPDATE task
SET status = 'WAITING', version = version + 1, updated_at = #{now}
WHERE id = #{taskId} AND version = #{expectedVer} AND status = 'RUNNING'

UPDATE task
SET version = version + 1, updated_at = #{now}
WHERE id = #{taskId} AND status = 'WAITING'
